-- Generated by `make contracts` from contracts/census_fips_county.odcs.yaml. Do not edit: change the contract and regenerate.
-- Types the latest raw load only; every business rule lives in intermediate models.
with raw as (
    select * from {{ source('raw', 'census_fips_county') }}
),

latest as (
    select * from raw where filename = (select max(filename) from raw)
)

select
  "STATE" AS "postal",
  "STATEFP" AS "state_fips",
  "COUNTYFP" AS "county_fips",
  "COUNTYNS" AS "county_ns",
  "COUNTYNAME" AS "county_name",
  "CLASSFP" AS "class_code",
  "FUNCSTAT" AS "functional_status"
from latest
qualify row_number() over (partition by "state_fips", "county_fips" order by filename desc) = 1
